<div class="section_box">
    <h3>Playground</h3>
    <div style="margin-bottom:15px;">
        <p>Enter values for the variables defined in the Config tab to test the query.</p>
        <div id="playground_inputs">
            <!-- Inputs generated by JS -->
        </div>
    </div>
    <div style="margin-bottom:15px;">
        <button type="button" class="devtool_btn" onclick="executePlayground()">Execute Query</button>
    </div>
    <div>
        <h4>Result</h4>
        <pre id="playground_result" style="background:#2d3748; color:#e2e8f0; padding:15px; border-radius:5px; overflow:auto; font-family:monospace; min-height:100px; max-height:600px; white-space:pre-wrap; word-wrap:break-word;"></pre>
    </div>
</div>

<script>
function renderPlayground(data) {
    var container = document.getElementById('playground_inputs');
    container.innerHTML = '';

    document.getElementById('playground_result').innerText = 'Ready to execute the query.';
    
    var vars = {};

    if (data) {
        if ((data.action === 'insert' || data.action === 'update') && data.columns) {
            data.columns.forEach(function(col) {
                var v = col.var || col.name;
                if (!v) return;
                if (!vars[v]) vars[v] = { default: '', notnull: false };
                if (col.default) vars[v].default = col.default;
                if (col.notnull === 'notnull' || col.notnull === 'Y') vars[v].notnull = true;
            });
        }
        if (data.conditions) {
            data.conditions.forEach(function(cond) {
                if (!cond.var) return;
                if (!vars[cond.var]) vars[cond.var] = { default: '', notnull: false };
                if (cond.default) vars[cond.var].default = cond.default;
                if (cond.notnull === 'notnull' || cond.notnull === 'Y') vars[cond.var].notnull = true;
            });
        }
        if (data.navigation) {
            data.navigation.forEach(function(nav) {
                if (!nav.var) return;
                if (!vars[nav.var]) vars[nav.var] = { default: '', notnull: false };
                if (nav.default) vars[nav.var].default = nav.default;
            });
        }
    }
    
    if (Object.keys(vars).length === 0) {
        container.innerHTML = '<p style="color:#666;">No variables found.</p>';
        return;
    }

    var table = document.createElement('table');
    table.className = 'devtool_info_table';
    table.innerHTML = '<thead><tr><th>Variable</th><th>Value</th><th>Default</th><th style="width:80px; text-align:center;">Required</th></tr></thead><tbody></tbody>';
    var tbody = table.querySelector('tbody');

    Object.keys(vars).forEach(function(k) {
        var v = vars[k];
        var tr = document.createElement('tr');
        var isRequired = v.notnull;
        var defaultVal = v.default || '';
        tr.innerHTML = `
            <td><label for="pg_input_${escapeHtml(k)}" style="font-weight:bold;">${escapeHtml(k)}</label></td>
            <td><input type="text" id="pg_input_${escapeHtml(k)}" class="devtool_input playground_var" data-var="${escapeHtml(k)}" value="${escapeHtml(defaultVal)}" style="width:100%;"></td>
            <td>${escapeHtml(defaultVal)}</td>
            <td style="text-align:center; color:${isRequired ? '#e53e3e' : '#718096'}; font-weight:${isRequired ? 'bold' : 'normal'};">${isRequired ? 'Yes' : 'No'}</td>
        `;
        tbody.appendChild(tr);
    });
    container.appendChild(table);
}

function executePlayground() {
    var queryId = document.getElementById('original_query_id').value;
    if (queryId === 'new') {
        alert('Please save the query first.');
        return;
    }

    var params = {};
    document.querySelectorAll('.playground_var').forEach(function(input) {
        var v = input.getAttribute('data-var');
        var val = input.value;
        if (val) params[v] = val;
    });

    document.getElementById('playground_result').innerText = 'Executing...';

    exec_json('devtool.getDevtoolQueryExecute', {
        target_module: targetModule,
        query_id: queryId,
        params: params
    }, function(ret) {
        if (ret.error) {
            document.getElementById('playground_result').innerText = 'Error: ' + ret.message;
        } else {
            document.getElementById('playground_result').innerText = '/** executeQuery("' + ret.target_module + '.' + ret.query_id + '", ' + toPhpArray(ret.params) + '); */\n\n' + 
                                                                    JSON.stringify(ret.output, null, 2);
        }
    }, function(err) {
        document.getElementById('playground_result').innerText = 'Error executing query.';
    });
}

function toPhpArray(obj) {
  const entries = Object.entries(obj)
    .map(([k, v]) => `"${k}" => ${JSON.stringify(v)}`)
    .join(', ');

  return `[${entries}]`;
}
</script>